import { promises as fs } from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";

export type BookStatus = "reading" | "finished";

export interface Book {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: BookStatus;
  addedAt: string;
  finishedAt: string | null;
}

export interface NewBook {
  title: string;
  author: string;
  notes?: string;
}

function booksFile(): string {
  return process.env.BOOKS_FILE ?? path.join(process.cwd(), "data", "books.json");
}

async function readAll(): Promise<Book[]> {
  let raw: string;
  try {
    raw = await fs.readFile(booksFile(), "utf8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw err;
  }
  if (raw.trim() === "") return [];
  const parsed: unknown = JSON.parse(raw);
  if (!Array.isArray(parsed)) {
    throw new Error(`${booksFile()} does not contain a JSON array`);
  }
  return parsed as Book[];
}

async function writeAll(books: Book[]): Promise<void> {
  const file = booksFile();
  await fs.mkdir(path.dirname(file), { recursive: true });
  const tmp = `${file}.${process.pid}.${Date.now()}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(books, null, 2) + "\n", "utf8");
  await fs.rename(tmp, file);
}

// Mutations are chained so overlapping requests can't interleave a read and a write.
let queue: Promise<unknown> = Promise.resolve();

function mutate<T>(fn: (books: Book[]) => Promise<T> | T): Promise<T> {
  const run = queue.then(async () => {
    const books = await readAll();
    const result = await fn(books);
    await writeAll(books);
    return result;
  });
  queue = run.catch(() => undefined);
  return run;
}

export async function listBooks(): Promise<Book[]> {
  return readAll();
}

export async function getBook(id: string): Promise<Book | undefined> {
  const books = await readAll();
  return books.find((b) => b.id === id);
}

export async function addBook(input: NewBook): Promise<Book> {
  const title = input.title.trim();
  const author = input.author.trim();
  if (!title) throw new Error("Title is required");
  if (!author) throw new Error("Author is required");

  const book: Book = {
    id: randomUUID(),
    title,
    author,
    notes: (input.notes ?? "").trim(),
    status: "reading",
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  await mutate((books) => {
    books.push(book);
  });
  return book;
}

export async function markFinished(id: string): Promise<Book | undefined> {
  return mutate((books) => {
    const book = books.find((b) => b.id === id);
    if (!book) return undefined;
    if (book.status !== "finished") {
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
    }
    return book;
  });
}

export async function updateNotes(id: string, notes: string): Promise<Book | undefined> {
  return mutate((books) => {
    const book = books.find((b) => b.id === id);
    if (!book) return undefined;
    book.notes = notes.trim();
    return book;
  });
}

