"use server";

import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import * as store from "./books";

export interface AddBookState {
  error?: string;
  values?: { title: string; author: string; notes: string };
}

function field(formData: FormData, name: string): string {
  const value = formData.get(name);
  return typeof value === "string" ? value : "";
}

export async function addBookAction(
  _prev: AddBookState,
  formData: FormData,
): Promise<AddBookState> {
  const values = {
    title: field(formData, "title"),
    author: field(formData, "author"),
    notes: field(formData, "notes"),
  };
  if (!values.title.trim()) return { error: "Please enter a title.", values };
  if (!values.author.trim()) return { error: "Please enter an author.", values };

  const book = await store.addBook(values);
  revalidatePath("/");
  redirect(`/books/${book.id}`);
}

export async function markFinishedAction(formData: FormData): Promise<void> {
  const id = field(formData, "id");
  if (!id) return;
  await store.markFinished(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

export async function updateNotesAction(formData: FormData): Promise<void> {
  const id = field(formData, "id");
  if (!id) return;
  await store.updateNotes(id, field(formData, "notes"));
  revalidatePath(`/books/${id}`);
}

