:root {
  --text: #1f2328;
  --muted: #667085;
  --border: #e4e7ec;
  --accent: #2f5d8a;
  --accent-text: #ffffff;
  --bg: #fbfbfa;
  --card: #ffffff;
  --error: #b42318;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
}

a {
  color: var(--accent);
}

main,
.site-header {
  max-width: 44rem;
  margin: 0 auto;
  padding: 0 1.25rem;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 1.5rem;
  padding-bottom: 1.5rem;
}

.site-title {
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--text);
  text-decoration: none;
}

main {
  padding-bottom: 3rem;
}

h1 {
  font-size: 1.75rem;
  margin: 0 0 0.25rem;
}

h2 {
  font-size: 1.1rem;
  margin: 2rem 0 0.75rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.muted {
  color: var(--muted);
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.book-list li a {
  display: block;
  padding: 0.75rem 1rem;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  text-decoration: none;
  color: inherit;
}

.book-list li a:hover {
  border-color: var(--accent);
}

.book-list .title {
  font-weight: 600;
}

.empty {
  padding: 1rem;
  border: 1px dashed var(--border);
  border-radius: 8px;
  color: var(--muted);
}

.button {
  display: inline-block;
  padding: 0.5rem 0.9rem;
  border: 1px solid var(--accent);
  border-radius: 6px;
  background: var(--accent);
  color: var(--accent-text);
  font: inherit;
  text-decoration: none;
  cursor: pointer;
}

.button.secondary {
  background: transparent;
  color: var(--accent);
}

.button:disabled {
  opacity: 0.6;
  cursor: default;
}

form.stack {
  display: grid;
  gap: 1rem;
  margin-top: 1.5rem;
}

label {
  display: grid;
  gap: 0.3rem;
  font-weight: 600;
}

input,
textarea {
  font: inherit;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--card);
  color: inherit;
  width: 100%;
}

textarea {
  min-height: 8rem;
  resize: vertical;
}

.error {
  color: var(--error);
  margin: 0;
}

.status {
  display: inline-block;
  font-size: 0.8rem;
  padding: 0.1rem 0.5rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  color: var(--muted);
}

.status.finished {
  border-color: #abefc6;
  background: #ecfdf3;
  color: #067647;
}

.book-actions {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  margin: 1.25rem 0;
}

.notes {
  white-space: pre-wrap;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  margin: 0;
}

details summary {
  cursor: pointer;
  color: var(--accent);
}

