import Link from "next/link";
import { listBooks, type Book } from "@/lib/books";

export const dynamic = "force-dynamic";

function BookList({ books, emptyText }: { books: Book[]; emptyText: string }) {
  if (books.length === 0) {
    return <p className="empty">{emptyText}</p>;
  }
  return (
    <ul className="book-list">
      {books.map((book) => (
        <li key={book.id}>
          <Link href={`/books/${book.id}`}>
            <div className="title">{book.title}</div>
            <div className="muted">{book.author}</div>
          </Link>
        </li>
      ))}
    </ul>
  );
}

export default async function HomePage() {
  const books = await listBooks();
  const reading = books
    .filter((b) => b.status === "reading")
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));

  return (
    <>
      <h2>Currently reading</h2>
      <BookList
        books={reading}
        emptyText="Nothing on the go right now. Add a book to get started."
      />

      <h2>Finished</h2>
      <BookList books={finished} emptyText="No finished books yet." />
    </>
  );
}

