import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { getBook } from "@/lib/books";
import { markFinishedAction, updateNotesAction } from "@/lib/actions";

export const dynamic = "force-dynamic";

type Props = { params: Promise<{ id: string }> };

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) return { title: "Book not found" };
  return {
    title: `${book.title} by ${book.author}`,
    description: book.notes ? book.notes.slice(0, 160) : `${book.title} by ${book.author}`,
  };
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

export default async function BookPage({ params }: Props) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  const finished = book.status === "finished";

  return (
    <article>
      <h1>{book.title}</h1>
      <p className="muted" style={{ marginTop: 0 }}>
        by {book.author}
      </p>

      <div className="book-actions">
        <span className={`status ${book.status}`}>
          {finished && book.finishedAt
            ? `Finished ${formatDate(book.finishedAt)}`
            : `Reading since ${formatDate(book.addedAt)}`}
        </span>
        {!finished && (
          <form action={markFinishedAction}>
            <input type="hidden" name="id" value={book.id} />
            <button type="submit" className="button">
              Mark as finished
            </button>
          </form>
        )}
      </div>

      <h2>Notes</h2>
      {book.notes ? (
        <p className="notes">{book.notes}</p>
      ) : (
        <p className="empty">No notes yet.</p>
      )}

      <details style={{ marginTop: "1rem" }}>
        <summary>Edit notes</summary>
        <form action={updateNotesAction} className="stack">
          <input type="hidden" name="id" value={book.id} />
          <label>
            Notes
            <textarea name="notes" defaultValue={book.notes} />
          </label>
          <div>
            <button type="submit" className="button secondary">
              Save notes
            </button>
          </div>
        </form>
      </details>
    </article>
  );
}

