import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";
import { addBook, getBook, listBooks, markFinished, updateNotes } from "./books";

let dir: string;

beforeEach(async () => {
  dir = await fs.mkdtemp(path.join(os.tmpdir(), "books-"));
  process.env.BOOKS_FILE = path.join(dir, "nested", "books.json");
});

afterEach(async () => {
  delete process.env.BOOKS_FILE;
  await fs.rm(dir, { recursive: true, force: true });
});

describe("books store", () => {
  it("starts empty when the file does not exist", async () => {
    expect(await listBooks()).toEqual([]);
  });

  it("adds a book as currently reading and persists it to disk", async () => {
    const book = await addBook({ title: "  Dune ", author: "Frank Herbert", notes: "sand" });
    expect(book.title).toBe("Dune");
    expect(book.status).toBe("reading");
    expect(book.finishedAt).toBeNull();

    const onDisk = JSON.parse(await fs.readFile(process.env.BOOKS_FILE!, "utf8"));
    expect(onDisk).toEqual([book]);
    expect(await getBook(book.id)).toEqual(book);
  });

  it("rejects a missing title or author", async () => {
    await expect(addBook({ title: " ", author: "x" })).rejects.toThrow(/title/i);
    await expect(addBook({ title: "x", author: "" })).rejects.toThrow(/author/i);
  });

  it("marks a book as finished exactly once", async () => {
    const book = await addBook({ title: "Emma", author: "Jane Austen" });
    const finished = await markFinished(book.id);
    expect(finished?.status).toBe("finished");
    expect(finished?.finishedAt).toBeTruthy();

    const again = await markFinished(book.id);
    expect(again?.finishedAt).toBe(finished?.finishedAt);
    expect(await markFinished("nope")).toBeUndefined();
  });

  it("updates notes", async () => {
    const book = await addBook({ title: "Emma", author: "Jane Austen" });
    await updateNotes(book.id, "  liked it  ");
    expect((await getBook(book.id))?.notes).toBe("liked it");
  });

  it("does not lose books when writes overlap", async () => {
    await Promise.all(
      Array.from({ length: 20 }, (_, i) => addBook({ title: `Book ${i}`, author: "A" })),
    );
    expect(await listBooks()).toHaveLength(20);
  });
});

